"""Build one editable Matplotlib Figure from packaged, existing results only."""
from pathlib import Path
from types import SimpleNamespace
import json
import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
import _plot_style as style

ROOT=Path(__file__).resolve().parent.parent
DATA=ROOT/'_data'

class _Ready(Exception):
    def __init__(self, fig):self.fig=fig

class _Monitor:
    def tick(self,*a,**k):pass

def _capture(target):
    def save(fig,path,*a,**k):
        if Path(path).stem==target:
            # The original shared save() removes grids before every export.
            for ax in fig.axes:ax.grid(False)
            raise _Ready(fig)
        plt.close(fig)
    return save

def _csv(folder,name):
    p=folder/name
    return pd.read_csv(p) if p.exists() else pd.DataFrame()

def _json(folder,name):
    p=folder/name
    return json.loads(p.read_text(encoding='utf-8-sig')) if p.exists() else {}

def _models(folder,target):
    import _plot_models as mod
    d=DATA/folder
    meta=_json(DATA,'families.json')[folder]
    fam=SimpleNamespace(**meta)
    fam.tasks=[SimpleNamespace(**t) for t in fam.tasks]
    fam.out=Path('.')
    fam.plot_data_dir=d
    scores=_csv(d,'scores.csv');tiers=_csv(d,'tiers.csv')
    oo=_csv(d,'oof_best_and_baseline.csv.gz')
    oof={t:{s:g.copy() for s,g in dt.groupby('scheme',sort=False)} for t,dt in oo.groupby('task',sort=False)}
    ee=_csv(d,'external_predictions.csv')
    ext={t:g.copy() for t,g in ee.groupby('task',sort=False)} if not ee.empty else {}
    cls={}
    for t,v in _json(d,'confusion_matrices.json').items():
        rows=ext.get(t,oof[t][fam.main_scheme])
        cls[t]={'source':v.get('source',''), 'confusion':{k:x for k,x in v.items() if k!='source'},'y':rows.y_true.to_numpy(),'p':rows.y_pred.to_numpy()}
    mod.save=_capture(target)
    mod.family_figures(fam,scores,tiers,_csv(d,'permutation_importance.csv'),oof,ext,cls,_csv(d,'learning_curve.csv').to_dict('records'),_json(d,'pdp.json'),_csv(d,'segment_errors.csv'))

def _summary():
    from _plot_config import HEADER,TIER_A
    tiers=pd.concat([pd.read_csv(p) for p in sorted(DATA.glob('M*/tiers.csv'))],ignore_index=True)
    fig,ax=plt.subplots(figsize=(max(12,.42*len(tiers)),5.2))
    x=np.arange(len(tiers));ax.bar(x,tiers.main_skill,color=[style.TIER_COLOR[v] for v in tiers.tier])
    ext=tiers.external_skill.to_numpy(float)
    ax.scatter(x[~np.isnan(ext)],ext[~np.isnan(ext)],marker='D',color='k',s=18,zorder=3,label='外部检验 skill（M3，只评一次）')
    ax.axhline(0,color='k',lw=.8);ax.axhline(TIER_A['skill'],color='#2ca02c',ls=':',lw=1)
    ax.set_xticks(x,[f'{a} · {b}' for a,b in zip(tiers.family,tiers.target_label)],rotation=75,ha='right',fontsize=7)
    ax.set_ylabel('主方案相对基线的改善 skill');ax.set_title('全部代理模型的临时表现分档（绿 A / 橙 B / 红 C）');ax.legend(fontsize=8)
    style.footnote(fig,HEADER+' 回归 skill=1−MAE/MAE基线；分类 skill=1−Brier/Brier基线。柱为开发集交叉验证成绩（含模型类别选择，略偏乐观）；分档只衡量对纠错前评分的预测能力，不是科研准入。',y=-.38)
    return fig

def draw(group,target):
    style.apply_style()
    try:
        if group=='p0':
            import _plot_p0 as mod
            old=style.save;style.save=_capture(target)
            try:mod.explore(_Monitor(),{k:pd.read_csv(DATA/(k+'.csv')) for k in ('D1','D2','D3','D4','D5')})
            finally:style.save=old
        elif group=='descriptive':
            import _plot_descriptive as mod
            mod.save=_capture(target)
            fn={'fig01':('fig01','D1'),'fig02':('fig02','D1'),'fig03':('fig03','D1'),'fig04':('fig04','D1'),'fig05':('fig05','D2','D4'),'fig06':('fig06','D3'),'fig07':('fig07','D5'),'fig12':('fig09',)}[target[:5]]
            getattr(mod,fn[0])(*[pd.read_csv(DATA/(k+'.csv')) for k in fn[1:]])
        elif group=='summary':return _summary()
        elif group=='case_svg':
            from _svg_replay import replay
            return replay(DATA/'case_svg'/(target+'.svg'))
        else:_models(group,target)
    except _Ready as ready:return ready.fig
    raise RuntimeError('Requested figure was not produced: '+target)
